	@Test
	void freeGraphContextIsProducedAcrossScopesAndEndpointShapes() {
		for (Scope scope : List.of(Scope.DEFAULT_CONTEXTS, Scope.NAMED_CONTEXTS)) {
			assertFreeContextRows(scope, Var.of("subject"), Var.of("object"),
					Set.of("subject", "object", "graph"), List.of(new PathRow(S, S, G), new PathRow(O, O, G)));
			assertFreeContextRows(scope, Var.of("subject", S, true, true), Var.of("object"),
					Set.of("object", "graph"), List.of(new PathRow(null, S, G)));
			assertFreeContextRows(scope, Var.of("subject"), Var.of("object", O, true, true),
					Set.of("subject", "graph"), List.of(new PathRow(O, null, G)));
			assertFreeContextRows(scope, Var.of("subject", S, true, true), Var.of("object", S, true, true),
					Set.of("graph"), List.of(new PathRow(null, null, G)));
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void fixedValuedGraphContextNeedsRequestAuthorityButIsNotUniversallyAssured(boolean apiAuthority) {
		Var graph = Var.of("graph", G, false, false).withApiInputOrigin();
		QueryBindingSet request = new QueryBindingSet();
		request.addBinding("graph", G);
		BindingSet input = EmptyBindingSet.getInstance();
		if (apiAuthority) {
			input = BindingSetOrigin.optimizationInput(request);
		}
		assertThat(input.hasBinding("graph")).isFalse();

		ZeroLengthPath path = new ZeroLengthPath(Scope.NAMED_CONTEXTS,
				Var.of("fixedSubject", S, true, true), Var.of("object"), graph);
		List<BindingSet> actual = evaluate(path, input, source(), new TupleFunctionRegistry());
		assertThat(actual).hasSize(1);
		assertThat(actual).singleElement().satisfies(row -> {
			assertThat(row.getValue("object")).isEqualTo(S);
			if (apiAuthority) {
				assertThat(row.getBindingNames()).containsExactlyInAnyOrder("object", "graph");
				assertThat(row.getValue("graph")).isEqualTo(G);
			} else {
				assertThat(row.getBindingNames()).containsExactly("object");
			}
		});
		assertPackedOutputProofs(path, actual, Set.of("object", "graph"));
		PackedQuery query = PackedQueryCodec.encode(path.clone());
		Set<String> assured = Set.copyOf(query.bindingNames(query.relAssuredMaskId(query.rootRelId())));
		assertThat(assured).contains("object").doesNotContain("graph");
	}

